package com.restaurant.pos.user;
import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.http.*; import org.keycloak.admin.client.*; import org.keycloak.representations.idm.UserRepresentation; import jakarta.validation.constraints.*; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/admin/users") @PreAuthorize("hasRole('ADMIN')") public class UserAdminController { record UserRequest(@NotBlank String username,@NotBlank String firstName,@NotBlank String lastName,@Email String email,@NotBlank String password,@NotBlank String role){} private Keycloak client(){return KeycloakBuilder.builder().serverUrl(System.getenv().getOrDefault("KEYCLOAK_URL","http://localhost:8081")).realm("master").clientId("admin-cli").username(System.getenv().getOrDefault("KEYCLOAK_ADMIN","admin")).password(System.getenv().getOrDefault("KEYCLOAK_ADMIN_PASSWORD","admin_dev_password")).build();}
 @GetMapping public List<UserRepresentation> all(){try(var k=client()){return k.realm("restaurant-pos").users().list();}} @PostMapping public ResponseEntity<?> create(@Valid @RequestBody UserRequest r){try(var k=client()){var u=new UserRepresentation();u.setUsername(r.username);u.setFirstName(r.firstName);u.setLastName(r.lastName);u.setEmail(r.email);u.setEnabled(true);var response=k.realm("restaurant-pos").users().create(u);if(response.getStatus()!=201)return ResponseEntity.status(response.getStatus()).build();String id=response.getLocation().getPath().replaceAll(".*/","");var credential=new org.keycloak.representations.idm.CredentialRepresentation();credential.setType("password");credential.setValue(r.password);credential.setTemporary(false);k.realm("restaurant-pos").users().get(id).resetPassword(credential);var role=k.realm("restaurant-pos").roles().get(r.role).toRepresentation();k.realm("restaurant-pos").users().get(id).roles().realmLevel().add(List.of(role));return ResponseEntity.status(201).body(Map.of("id",id));}}
}
